mapper.select:
SELECT  FROM assessment_homework h WHERE h.deleted = 0

    AND (h.teacher_user_id = #{userId} OR (h.status IN ('PUBLISHED','CLOSED') AND EXISTS (
        SELECT 1 FROM assessment_homework_recipient r WHERE r.homework_id = h.id AND r.student_user_id = #{userId}
    )))

ORDER BY h.updated_time DESC, h.id DESC LIMIT #{size} OFFSET #{offset}
